using System.Text.RegularExpressions; namespace Axis.Core.Projects; internal static class ResumePatterns {
 internal static readonly Regex GENERIC=new(@"^(?:continue|resume) in the synced chatgpt thread\.?$|^chatgpt thread synced\.?$|^review the newest evidence and choose the next safe action\.?$",RegexOptions.IgnoreCase|RegexOptions.CultureInvariant|RegexOptions.ECMAScript,TimeSpan.FromMilliseconds(100));
 internal static readonly Regex NOISY=new(@"```|powershell|executionpolicy|\bps [a-z]:\\|traceback|exception:|stack trace|\bget-[a-z]|\bset-[a-z]|project api count|active-tab|no_api_inventory_result",RegexOptions.IgnoreCase|RegexOptions.CultureInvariant|RegexOptions.ECMAScript,TimeSpan.FromMilliseconds(100));
 internal static readonly Regex NO_ACTION=new(@"\b(no remaining work|nothing left|no further action|no action required|nothing to do|fully complete|closeout complete|finished)\b",RegexOptions.IgnoreCase|RegexOptions.CultureInvariant|RegexOptions.ECMAScript,TimeSpan.FromMilliseconds(100));
 internal static readonly Regex ACTION=new(@"\b(next|todo|to-do|remaining|resume|retest|verify|validate|test|check|open|run|launch|fix|correct|continue|finish|complete|build|implement|wire|merge|deploy|send|reply|compare|choose|select|review|audit|wait|monitor|install|configure|calibrate|measure|try|retry|reproduce|confirm|create|write|update|remove|replace|add|move|connect|scan|sync)\b",RegexOptions.IgnoreCase|RegexOptions.CultureInvariant|RegexOptions.ECMAScript,TimeSpan.FromMilliseconds(100));
 internal static readonly Regex OPEN_STATE=new(@"\b(pending|blocked|remaining|still needs?|not done|not finished|waiting|next step|to do|todo|retest|required|needs? to|must|should)\b",RegexOptions.IgnoreCase|RegexOptions.CultureInvariant|RegexOptions.ECMAScript,TimeSpan.FromMilliseconds(100));
 internal static readonly Regex CLOSED_ONLY=new(@"^.*\b(done|complete|completed|merged|fixed|validated|working|works|shipped|green|pass(?:ed)?)\b[.!]?$",RegexOptions.IgnoreCase|RegexOptions.CultureInvariant|RegexOptions.ECMAScript,TimeSpan.FromMilliseconds(100));
}
